import {startPan,panView,startPinch,pinchView} from './gestures.mjs';
export async function renderDoors(root,esc){root.textContent='Cargando Puertas · nivel −1…';const response=await fetch('doors/catalog.json');if(!response.ok)throw Error('No se pudo cargar el plano de puertas');const data=await response.json();if(!root.isConnected)return;
 root.innerHTML='<div class="disciplineTools"><strong>Puertas · Nivel −1</strong><input id="doorSearch" placeholder="Recinto, tipo o llave" aria-label="Buscar puertas"><button id="doorFit">Ajustar</button><button id="doorIn">+</button><button id="doorOut">−</button><a href="doors/puertas-unidas.pdf" target="_blank">PDF unido ↗</a></div><p class="doorNote">Dos láminas unidas por los ejes AH, AI y AJ. Toca una etiqueta de recinto o una llave de puerta. Las correspondencias por proximidad requieren revisión.</p><div id="doorResults"></div><div class="specialtyCanvas"><svg id="doorsSVG" role="img" aria-label="Plano unido de puertas"><g id="doorImages"></g><g id="doorMarks"></g></svg></div><aside id="specialtyDetail"><h2>Selecciona un recinto o una puerta</h2><p>La ficha mostrará código, tipo y llave. No utiliza rombos.</p></aside>';
 const svg=root.querySelector('svg'),images=root.querySelector('#doorImages'),marks=root.querySelector('#doorMarks'),detail=root.querySelector('#specialtyDetail'),ns=svg.namespaceURI;let view=[0,0,data.width,data.height],selected=null,drag,gesture,moved=false;const pointers=new Map();
 function render(){if(!root.isConnected)return;svg.setAttribute('viewBox',view.join(' '));const rect=svg.getBoundingClientRect(),scale=rect.width/view[2],visible=data.tiles.filter(t=>t[0]<view[0]+view[2]&&t[0]+t[2]>view[0]&&t[1]<view[1]+view[3]&&t[1]+t[3]>view[1]);images.innerHTML='<image href="doors/overview.webp" width="'+data.width+'" height="'+data.height+'"/>'+(scale>.35?visible.map(t=>'<image x="'+t[0]+'" y="'+t[1]+'" width="'+t[2]+'" height="'+t[3]+'" href="doors/'+t[4]+'"/>').join(''):'');marks.innerHTML=data.doors.map((d,i)=>'<rect data-door="'+i+'" x="'+(d.position[0]-19)+'" y="'+(d.position[1]-7)+'" width="38" height="14" fill="'+(selected===i?'#ffbd24':'transparent')+'" fill-opacity=".45" stroke="'+(selected===i?'#175d89':'#4b7b92')+'" stroke-width="1" vector-effect="non-scaling-stroke"><title>'+esc((d.type||'Tipo pendiente')+' · '+d.key)+'</title></rect>').join('');}
 const table=doors=>doors.map(d=>'<article><h2 style="font-size:28px">'+esc(d.type||'Tipo pendiente de lectura')+'</h2><h3 style="font-size:22px">'+esc(d.key)+'</h3><small>Fuente: Puerta '+d.source+' · Llave original. Vinculación con recinto pendiente de validación.</small></article>').join('')||'<p>No hay puertas cercanas vinculables por texto. Revisa las etiquetas del plano.</p>';
 function chooseDoor(i){selected=i;const d=data.doors[i];detail.innerHTML='<div class="section-label">PUERTA · FICHA DOCUMENTAL</div><h2 style="font-size:30px">Recinto: pendiente de confirmar</h2>'+table([d])+'<p>Códigos cercanos, sin vínculo confirmado: '+esc(d.roomCandidates.map(c=>c.code).join(' / '))+'</p>';view=[d.position[0]-180,d.position[1]-160,360,320];render();}
 function chooseRoom(room){selected=null;detail.innerHTML='<div class="section-label">RECINTO · PUERTAS</div><h2 style="font-size:32px">'+esc(room.code)+'</h2><p>Estas puertas son candidatas por cercanía, no una asignación técnica confirmada:</p>'+table(data.doors.filter(d=>d.roomCandidates[0]?.code===room.code));view=[room.position[0]-220,room.position[1]-180,440,360];render();}
 const zoom=k=>{view=[view[0]+view[2]*(1-k)/2,view[1]+view[3]*(1-k)/2,view[2]*k,view[3]*k];render();};root.querySelector('#doorFit').onclick=()=>{view=[0,0,data.width,data.height];render();};root.querySelector('#doorIn').onclick=()=>zoom(.7);root.querySelector('#doorOut').onclick=()=>zoom(1.4);
 root.querySelector('#doorSearch').oninput=e=>{const q=e.target.value.toLowerCase().trim(),result=root.querySelector('#doorResults');result.replaceChildren();if(!q)return;for(const r of data.rooms.filter(r=>r.code.includes(q)).slice(0,30)){const button=document.createElement('button');button.textContent=r.code;button.onclick=()=>chooseRoom(r);result.append(button);}data.doors.forEach((d,i)=>{if(result.children.length>=60||!(d.key+' '+d.type).toLowerCase().includes(q))return;const button=document.createElement('button');button.textContent=d.type+' · '+d.key;button.onclick=()=>chooseDoor(i);result.append(button);});};
 svg.onpointerdown=e=>{svg.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});moved=false;if(pointers.size===2)gesture=startPinch(view,svg.getScreenCTM(),...[...pointers.values()]);else drag=startPan(view,svg.getScreenCTM(),{x:e.clientX,y:e.clientY});};svg.onpointermove=e=>{if(!pointers.has(e.pointerId))return;const p=pointers.get(e.pointerId);if(Math.hypot(p.x-e.clientX,p.y-e.clientY)>3)moved=true;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(gesture&&pointers.size===2)view=pinchView(gesture,...pointers.values(),data.width*3);else if(drag&&moved)view=panView(drag,{x:e.clientX,y:e.clientY});if(moved)render();};svg.onpointerup=e=>{const click=!moved&&pointers.size===1;pointers.delete(e.pointerId);drag=null;gesture=null;if(!click)return;const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse()),target=e.target.closest('[data-door]');if(target){chooseDoor(Number(target.dataset.door));return;}const room=data.rooms.map(r=>({r,d:Math.hypot(r.position[0]-p.x,r.position[1]-p.y)})).sort((a,b)=>a.d-b.d)[0];if(room?.d<50)chooseRoom(room.r);};svg.onpointercancel=()=>{pointers.clear();drag=null;gesture=null;};svg.onwheel=e=>{e.preventDefault();zoom(e.deltaY>0?1.15:.87);};render();
}
